/// <summary>
///     The <c>AVAsmmBusRelTableFrm_Extension</c> class is the extension for <c>smmBusRelTable</c>
/// </summary>
[ExtensionOf(FormStr(smmBusRelTable))]
final class AVAsmmBusRelTableFrm_Extension
{
    public  DirPartyTable   frmDirPartyTable;
    public  DirPartyRecId   frmDirPartyRecId, frmDirPartyRecId1, frmDirPartyRecId2, frmDirPartyRecId3;
    public  DirPartyName    frmDirPartyName;

    public  DirPartyType    allowedParentType;
    public  DirPartyType    allowedChildType;

    public  smmBusRelTable  createdSmmBusRelTable; 


}

