/// <summary>
///    AVA <c>aftersmmBusRelTableCretion</c> method.
/// </summary>
/// <param name="_frmDirPatrtyTable">
///    <c>DirPartyTable</c> as type
/// </param>
/// <returns>
///    <c>DirPartyTable</c> as return value
/// </returns>
public DirPartyTable parmDirGroupPartyTable(DirPartyTable _frmDirPatrtyTable = frmDirPartyTable)
{
    frmDirPartyTable = _frmDirPatrtyTable;
    return frmDirPartyTable;
}

/// <summary>
///    AVA <c>aftersmmBusRelTableCretion</c> method.
/// </summary>
public void AVAaftersmmBusRelTableCreation()
{
    smmBusRelTable_DS.research();
    AVADirPartyAddressPrimary_DS.research();
    smmBusRelTable_DS.executeQuery();
    AVADirPartyAddressPrimary_DS.executeQuery();
}

/// <summary>
///    AVA <c>getAllowedChildType</c> method.
/// </summary>
/// <returns>
///    <c>DirPartyType</c> as return value
/// </returns>
public DirPartyType getAllowedChildType()
{
    return allowedChildType;
}

/// <summary>
///    AVA <c>getAllowedParentType</c> method.
/// </summary>
/// <returns>
///    <c>DirPartyType</c> as return value
/// </returns>
public DirPartyType getAllowedParentType()
{
    return allowedParentType;
}

/// <summary>
///    AVA <c>getAllowedPartyTypes</c> method.
/// </summary>
void getAllowedPartyTypes()
{
    if (dirPartyRelationship.RelationshipTypeId != dirRelationshipTypeTable.RelationshipTypeId)
    {
        dirRelationshipTypeTable.data(DirRelationshipTypeTable::find(dirPartyRelationship.RelationshipTypeId));
    }
    [allowedParentType, allowedChildType] = [dirRelationshipTypeTable.ParentPartyType, dirRelationshipTypeTable.ChildPartyType];
}

/// <summary>
///    AVA <c>updateRange</c> method.
/// </summary>
/// <param name="_dataSource">
///    <c>FormDataSource</c> as type
/// </param>
public void updateRange(FormDataSource _dataSource)
{
    QueryBuildDataSource    qbd;
    QueryBuildRange         qbRange;
    str                     qStr;

    qbd = _dataSource.query().dataSourceTable(tableNum(DirPartyRelationship));
    qStr = strFmt(  '((%1.%2 == %4) || (%1.%3 == %4))',
                    qbd.name(), fieldStr(DirPartyRelationship, ParentParty),
                    fieldStr(DirPartyRelationship,ChildParty), dirPartyTable.RecId);

    qbRange = SysQuery::findOrCreateRange(qbd, fieldNum(DirPartyRelationship, RecId));
    qbRange.status(RangeStatus::Locked);
    qbRange.value(qStr);
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_smmBusRelTable">smmBusRelTable</param>
public void AVAsetContext(smmBusRelTable _smmBusRelTable)
{
    FormDataSource       busRelTableDS = this.dataSource('smmBusRelTable');
    smmBusRelTable       smmBusRelTable = smmBusRelTable::findRec(_smmBusRelTable.RecId);
    if (busRelTableDS)
    {
        busRelTableDS.reread();
        busRelTableDS.positionToRecord(smmBusRelTable);
    }
}

/// <summary>
/// AVA
/// </summary>
/// <param name = "_smmBusRelTable">smmBusRelTable</param>
public void AVAsetContextFindRecord(smmBusRelTable _smmBusRelTable)
{
    FormDataSource       busRelTableDS = this.dataSource('smmBusRelTable');
    if (busRelTableDS)
    {

        busRelTableDS.query().dataSourceTable(tableNum(smmBusRelTable)).addSortField(fieldNum(smmBusRelTable,BusRelAccount),SortOrder::Descending);
        busRelTableDS.executeQuery();

    }   
    createdSmmBusRelTable = _smmBusRelTable;
}

/// <summary>
/// designed from AVA
/// </summary>
/// <param name = "_smmBusRelTable">_smmBusRelTable</param>
public void setContext(smmBusRelTable _smmBusRelTable)
{
    FormDataSource       busRelTableDS = this.dataSource('smmBusRelTable');
    smmBusRelTable       smmBusRelTable = smmBusRelTable::findRec(_smmBusRelTable.RecId);
  //  smmBusRelTableFindRecordFlightIsEnabled = true;
    if (busRelTableDS)
    {
        busRelTableDS.reread();
    }
    next setContext(smmBusRelTable);
}
